mat2 rot2D(float angle){
     float s = sin(angle);
     float c = cos(angle);
     return mat2(c,-s,s,c);

}

const mat2 m2 = mat2(  0.80,  0.60,
                      -0.60,  0.80 );
const mat2 m2i = mat2( 0.80, -0.60,
                       0.60,  0.80 );

float shuffle(in vec2 ij){

    ij  = 50.0*fract( ij*0.3183099 );
    return fract( ij.x*ij.y*(ij.x+ij.y) );

}

vec2 hash(in vec2 p ){

    vec2 n = vec2(107. * p.x,113. * p.y) + 131.;
    vec2 nm = fract(n * fract(vec2(n.y  * 0.3183094559, n.x * 0.3678788901)));
    return nm;


}

float noise(in vec2 x){

    vec2 p = floor(x);
    vec2 w = fract(x);

    vec2 u = w*w*w*(w*(w*6.0-15.0)+10.0);



    float a = shuffle(p+vec2(0.,0.));
    float b = shuffle(p+vec2(1.,0.));
    float c = shuffle(p+vec2(0.,1.));
    float d = shuffle(p+vec2(1.,1.));

    return a + (b - a) * u.x + (c - a) * u.y + (a-b-c+d) * u.x * u.y;
}



vec3 noised( in vec2 x )
{
    vec2 p = floor(x);
    vec2 w = fract(x);
    vec2 u = w*w*w*(w*(w*6.0-15.0)+10.0);
    vec2 du = 30.0*w*w*(w*(w-2.0)+1.0);


    float a = shuffle(p+vec2(0,0));
    float b = shuffle(p+vec2(1,0));
    float c = shuffle(p+vec2(0,1));
    float d = shuffle(p+vec2(1,1));

    float k0 = a;
    float k1 = b - a;
    float k2 = c - a;
    float k4 = a - b - c + d;

    return vec3( -1.0+2.0*(k0 + k1*u.x + k2*u.y + k4*u.x*u.y), 
                 2.0*du * vec2( k1 + k4*u.y,
                            k2 + k4*u.x ) );
}

float fbm_9( in vec2 x , in int am, in int stop, in int go)
{
    float f = 1.9;
    float s = 1./f;
    float a = 0.0;
    float b = 0.5;
    for( int i=0; i<stop; i++ )
    {
        float n = noise(x);
        a += b*n;
        b *= s;
        x = f*m2*x;
    }

    for( int i=go; i<am; i++ )
    {
        float n = noise(x);
        a += b*n;
        b *= s;
        x = f*m2*x;
    }

	return a;
}


vec3 fbmd_9( in vec2 x , in int am, in int stop, in int go)
{
    float f = 1.9;
    float s = 1./f;
    float a = 0.0;
    float b = 0.5;
    vec2  d = vec2(0.0);
    mat2  m = mat2(1.0,0.0,0.0,1.0);
    for( int i=0; i<stop; i++ )
    {
        vec3 n = noised(x);
        a += b*n.x;          		
        d += b*m*n.yz;       
        b *= s;
        x = f*m2*x;
        m = f*m2i*m;
    }
    for( int i=go; i<am; i++ )
    {
        vec3 n = noised(x);
        a += b*n.x;          		
        d += b*m*n.yz;       
        b *= s;
        x = f*m2*x;
        m = f*m2i*m;
    }

	return vec3( a, d );
}


float SDF(in vec3 pos)
{
