//Sky

float CloudCol( in vec3 rayPos, in vec3 rayDir){

    float t = (2500. - rayPos.y) / rayDir.y;
    vec2 Pos = t * rayDir.xz + rayPos.xz;

    float st = smoothstep(0.,0.9,fbm_9(Pos/500.,6,3,3));
    return st;

}





//Terrain

vec2 terrainMap( in vec2 p )
{
    float e = fbm_9(p/2000.,19,7,13);
    e*= 1400.;
    e+= clamp((e - 600.),0.,200.);
    float a = e/1000.;
    return vec2(e,a);
}


vec4 terrainMapD( in vec2 p )
{
    vec3 e = fbmd_9(p/2000.,19,7,13);
    e*= 1400.; 
    e+= clamp((e - 600.),0.,200.); 
    e.yz /= 2000.0;
    return vec4( e.x, normalize( vec3(-e.y,1.0,-e.z) ) );
}

float terrainShadow( in vec3 ro, in vec3 rd)
{
    ro += vec3(0.,0.5,0.);
    float res = 1.0;
    float t = 0.5;
    for( int i=0; i<64; i++ )
    {
        vec3  pos = ro + t*rd;
        vec2  env = terrainMap( pos.xz );
        float hei = pos.y - env.x;
        res = min( res, 4.0*hei/t );
        if( res<0.0001 || pos.y>1400. ) break;
        t += clamp( hei, 1.0+t*0.05, 100.0 );
    }
       return clamp( res, 0.1, 1.0 );
}

//Trees

float TreeMap(in vec3 pos){

    vec2 m = floor(pos.xz/2.);
    vec2 n = hash(m);
    vec2 c = 2. * m + n +1./2.;
    vec3 w = vec3(pos.x - c.x,pos.y - terrainMap(c).x - .5,pos.z - c.y);
    return length(w) - 0.8;

}

vec3 TreeMapD(in vec3 pos){

    vec2 m = floor(pos.xz/2.);
    vec2 n = hash(m);
    vec2 c = 2. * m + n + 1./2.;
    vec3 w = vec3(pos.x - c.x,pos.y - terrainMap(c).x - .5,pos.z - c.y);



    return normalize(w);

}

