//Stars
float Stars(in vec3 rayPos, in vec3 rayDir){

    float t = (100000. - rayPos.y) / rayDir.y;
    vec2 Pos = t * rayDir.xz + rayPos.xz;

    float st = smoothstep(0.,0.9,fbm_9(Pos/750.,6,0,4));
    return smoothstep(0.9,1.,st * 1.1);



}





void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = (fragCoord*2.0-iResolution.xy)/iResolution.y;
    vec2 m = (iMouse.xy * vec2(4.0, 2.0) - iResolution.xy) / iResolution.y;
    //m = vec2(m.x + iTime * .3,m.y);


    float zoom = 1.;

    vec3 cameraDir = normalize(vec3(-1.,0.,1.));
    vec3 cameraPos = vec3(310.,410.,290.);

    vec3 rayDir = normalize(vec3(uv.x*0.25 * zoom ,uv.y*.5 * zoom,uv.x*0.25 * zoom) + cameraDir); 
    vec3 rayPos = cameraPos;

    float sdir = 1.5;
    float stime = 6.5 + 8. * .3;

    vec3 SunDir = normalize(vec3(sin(stime) * sin(sdir), cos(stime), sin(stime) * cos(sdir)));

    float iterations = 1500.;
    float maxDist = 50000.;
    float minDist = 0.0015;
    //rayDir.yz *= rot2D(-m.y);
    //rayDir.xz *= rot2D(-m.x);
    float ot = 0.;
    float d,th;
    float od = 0.;
    float t = 0.;
    float i = 0.;

    float matHit = 0.; //0 = Normal 1 = Tree

    float hit = 0.;
    vec3 norm = vec3(1.);

    vec3 p;
    //raymarching
    for(i = 0.; i<iterations;i++){

        th = 0.001*t;

        p = rayDir * t + rayPos;
        vec2  env = terrainMap( p.xz );
        //float treeD = TreeMap(p);
        float hei = env.x;
        ot = t;
        od = d;

        d = p.y - hei;
        //d = min(d,treeD);
        t += d * 0.3; 
        if(d < minDist){

            hit = 1.0;
            /*if(treeD  == d){

            matHit = 1.;

            } */
            break;
        }

        if(p.y >  2500.){

            hit = 0.;
            break;


        }

        if(t > maxDist){hit = 0.;break;}


    }
    if( t>maxDist ) t = -1.0;
    else t = ot + (th-od)*(t-ot)/(d-od);

    vec3 brown = vec3(180.,160.,200.) / 255.;
    vec3 Snow = vec3(1.);
    vec3 skyBlue = vec3(135.,206.,235.) / 255. * 1.;
    vec3 GrassGreen = vec3(106.,150,60.)/255.;

    p = rayDir * t + rayPos;
    norm = terrainMapD(p.xz).yzw; 
    vec3 b = -SunDir;

    float SnowStrength = smoothstep(0.55,0.7,norm.y);
    float GrassStrength = smoothstep(0.55,0.7,norm.y);
    float SwitchGrassSnow = smoothstep(250.,400.,p.y);

    vec3 SnowGrass = GrassGreen * (1.-SwitchGrassSnow) + Snow * SwitchGrassSnow;
    vec3 material;
    if(matHit == 0.){

        material = brown * (1.-SnowStrength) + SnowGrass * SnowStrength;



    }
    else{
        norm = TreeMapD(p);
        material =  GrassGreen;


    }

    vec3 TextureCol =  material;
    vec3 lightCol = (smoothstep(-0.1,1.,dot(norm,SunDir)) * terrainShadow(p,SunDir) + ((1.+norm.y)/2.) * skyBlue/4. + dot(norm,b)/8.);
    TextureCol = TextureCol * lightCol; 
    float y = exp(-0.00020 * t);



    vec3 col =  y * TextureCol + (1. - y)* vec3(1.,2.,4.)/1.5;
    if (hit == 0.){
        float yt = CloudCol(rayPos,rayDir) + clamp(-1.,0.,SunDir.y);
        float star = Stars(rayPos,rayDir);
        col = skyBlue - (0.6 * uv.y - clamp(-1.,0.,SunDir.y) * .6 - 0.4);
        col = col * (1. - yt) + yt * vec3(0.3);
        col = col * (1.-star) + star * vec3(1.);
    }

    col = smoothstep(0.,1.,col);
    col = col + clamp(-.1,-0.4, uv.y) * .25 + .1;

    fragColor = vec4(col,1.0);
}
